import {
    PaginationState,
    Row,
    getCoreRowModel,
    useReactTable,
  } from '@tanstack/react-table';
  import React, { CSSProperties, useMemo, useState } from 'react';
  import {
    IExpense,
    IExpenseData,
  } from '../../core/Interface/expense.interface';
  import usePageQuery from '../../core/hooks/usePageQuery';
  import { useGetAllExpensesQuery } from '../posApi';
  import useExpenseDetailsColumn from './useExpenseDetailsColumn';

const useExpenseDetails = (
  handleEdit: (data: IExpense) => void,
  handleConfirmDelete: (data: IExpense) => void
) => {
  const { page } = usePageQuery();
  const [pagination, setPagination] = React.useState<PaginationState>({
    pageIndex: page,
    pageSize: 10,
  });
  const [searchText, setSearchText] = useState('');

  const {
    data: expenseData,
    isLoading,
    isFetching,
    error,
  } = useGetAllExpensesQuery({
    pageIndex: pagination.pageIndex,
    pageSize: pagination.pageSize,
    searchText,
  });

  const expenseDetailsMemo = useMemo(() => {
    return expenseData?.data as IExpenseData;
  }, [expenseData?.data]);

  const filteredData = useMemo(() => {
    const text = searchText.toLowerCase().trim();
    return expenseDetailsMemo?.records.filter((record) => {
      const typeId = record.typeId?.toLowerCase();
      // const name = record.name?.toLowerCase();
      return typeId?.includes(text);
    });
  }, [expenseDetailsMemo, searchText]);

  const columns = useExpenseDetailsColumn(handleEdit, handleConfirmDelete);

  const table = useReactTable({
    data: error ? [] : filteredData,
    meta: {
      getRowStyles: (row: Row<IExpense>): CSSProperties => ({}),
    },
    columns: columns,
    initialState: {
      columnVisibility: {
        id: false,
      },
    },
    pageCount: expenseDetailsMemo?.totalRecords ?? 0,
    // pageCount: 10,
    state: {
      pagination,
    },
    onPaginationChange: setPagination,
    getCoreRowModel: getCoreRowModel(),
    manualPagination: true,
  });

  return {
    table,
    isLoading: isFetching || isLoading,
    isInitLoading: isLoading,
    error,
    totalCount: expenseDetailsMemo?.totalRecords ?? 0,
    // totalCount:  10,
    searchText,
    setSearchText,
  };
};

export default useExpenseDetails