import {
  Box,
  Button,
  Chip,
  InputAdornment,
  Paper,
  TextField,
  Typography,
} from '@mui/material';
import { Table } from '@tanstack/react-table';
import React, { useState, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { IExpense } from '../../core/Interface/expense.interface';
import PosTablePagination from '../../components/Table/PosTablePagination';
import ReactTable from '../../components/Table/ReactTable';
import useExpenseDetails from './useExpenseDetails';
import { useDeleteExpensesMutation } from '../posApi';
import usePageQuery from '../../core/hooks/usePageQuery';
import SearchIcon from '@mui/icons-material/Search';
import AddIcon from '@mui/icons-material/Add';
import ReceiptLongOutlinedIcon from '@mui/icons-material/ReceiptLongOutlined';
import { useNotifier } from '../../core/Notifier';
import AnimatedPage from '../../layouts/AnimatedPage';
import NewExpense from './Components/NewExpense';
import DeletePopup from '../../components/ModelPopup/DeletePopup';
import { HEADER_GRADIENT } from '../../theme/appColors';

const Expense = () => {
  const { t } = useTranslation(['common', 'expense']);
  const [expenseData, setExpenseData] = React.useState<IExpense | undefined>();
  const { setPage } = usePageQuery();
  const { showErrorMessage, showMessage } = useNotifier();
  const [openExpense, setOpenExpense] = useState(false);
  const [openDeleteExpense, setOpenDeleteExpense] = useState(false);
  const [expenseNameToDelete, setExpenseNameToDelete] = useState('');
  const [expenseToDelete, setExpenseToDelete] = useState<IExpense | null>(null);
  const [localSearch, setLocalSearch] = useState('');

  const handleEdit = (data: IExpense) => {
    setExpenseData(data);
    setOpenExpense(true);
  };

  const [deleteExpense] = useDeleteExpensesMutation();

  const handleConfirmDelete = (expense: IExpense) => {
    setExpenseToDelete(expense);
    setOpenDeleteExpense(true);
    setExpenseNameToDelete(expense.type.name);
  };

  const handleDelete = async () => {
    if (!expenseToDelete) return;
    try {
      const response = await deleteExpense(expenseToDelete.id).unwrap();
      if (response.status) {
        showMessage(response.message);
        setOpenDeleteExpense(false);
        setExpenseToDelete(null);
      } else {
        showErrorMessage(response.message);
      }
    } catch (error) {
      showErrorMessage((error as Error).message);
    }
  };

  const { table, isLoading, totalCount, setSearchText } =
    useExpenseDetails(handleEdit, handleConfirmDelete);

  const handlePaginationChangePage = (
    _event: React.MouseEvent<HTMLButtonElement> | null,
    newPage: number
  ) => {
    table.getState().pagination.pageIndex < newPage
      ? table.nextPage()
      : table.previousPage();
    setPage(newPage);
  };

  const handleChangeRowsPerPage = (event: React.ChangeEvent<HTMLInputElement>) => {
    table.setPageSize(parseInt(event.target.value, 10));
  };

  useEffect(() => {
    if (!isLoading && table.getState().pagination.pageIndex !== 0 && table.getRowModel().rows.length === 0) {
      setPage(0);
    }
  }, [isLoading, setPage, table]);

  return (
    <AnimatedPage>
      <Box data-testid="addressDetails">
        {/* Hero Panel */}
        <Paper
          elevation={0}
          sx={{ background: HEADER_GRADIENT, borderRadius: 2, mb: 2, overflow: 'hidden' }}
        >
          <Box
            sx={{
              alignItems: 'center',
              display: 'flex',
              flexWrap: 'wrap',
              gap: 2,
              justifyContent: 'space-between',
              px: 3,
              py: 2,
            }}
          >
            {/* Title */}
            <Box sx={{ alignItems: 'center', display: 'flex', gap: 1.5 }}>
              <Box
                sx={{
                  alignItems: 'center',
                  background: 'rgba(255,255,255,0.15)',
                  borderRadius: '10px',
                  display: 'flex',
                  height: 40,
                  justifyContent: 'center',
                  width: 40,
                }}
              >
                <ReceiptLongOutlinedIcon sx={{ color: '#fff', fontSize: 22 }} />
              </Box>
              <Box>
                <Typography sx={{ color: '#fff', fontSize: 18, fontWeight: 800, lineHeight: 1.2 }}>
                  Expenses
                </Typography>
                <Typography sx={{ color: 'rgba(255,255,255,0.65)', fontSize: 12, fontWeight: 500 }}>
                  All expense records
                </Typography>
              </Box>
              {totalCount > 0 && (
                <Chip
                  label={`${totalCount} records`}
                  size="small"
                  sx={{
                    background: 'rgba(255,255,255,0.18)',
                    border: '1px solid rgba(255,255,255,0.3)',
                    color: '#fff',
                    fontSize: 11,
                    fontWeight: 600,
                  }}
                />
              )}
            </Box>

            {/* Search + Add */}
            <Box sx={{ alignItems: 'center', display: 'flex', gap: '10px' }}>
              <TextField
                InputProps={{
                  startAdornment: (
                    <InputAdornment position="start">
                      <SearchIcon sx={{ color: 'rgba(255,255,255,0.7)', fontSize: 18 }} />
                    </InputAdornment>
                  ),
                }}
                onChange={(e) => setLocalSearch(e.target.value)}
                onKeyDown={(e) => { if (e.key === 'Enter') setSearchText(localSearch); }}
                placeholder="Search name or code…"
                size="small"
                sx={{
                  minWidth: 260,
                  '& .MuiOutlinedInput-root': {
                    background: 'rgba(255,255,255,0.12)',
                    borderRadius: '8px',
                    color: '#fff',
                    height: 40,
                    '& fieldset': { borderColor: 'rgba(255,255,255,0.25)' },
                    '&:hover fieldset': { borderColor: 'rgba(255,255,255,0.5)' },
                    '&.Mui-focused fieldset': { borderColor: 'rgba(255,255,255,0.8)' },
                    '& input::placeholder': { color: 'rgba(255,255,255,0.55)', opacity: 1 },
                  },
                }}
                value={localSearch}
                variant="outlined"
              />
              <Button
                onClick={() => setSearchText(localSearch)}
                sx={{
                  background: 'rgba(255,255,255,0.15)',
                  border: '1px solid rgba(255,255,255,0.3)',
                  borderRadius: '8px',
                  color: '#fff',
                  flexShrink: 0,
                  fontWeight: 600,
                  height: 40,
                  px: 2.5,
                  '&:hover': { background: 'rgba(255,255,255,0.25)' },
                }}
                variant="contained"
              >
                {t('common:search')}
              </Button>

              <Button
                onClick={() => { setExpenseData(undefined); setOpenExpense(true); }}
                startIcon={<AddIcon />}
                sx={{
                  background: 'linear-gradient(135deg, #2563EB 0%, #1d4ed8 100%)',
                  borderRadius: '8px',
                  boxShadow: '0 4px 14px rgba(37,99,235,0.35)',
                  color: '#fff',
                  flexShrink: 0,
                  fontWeight: 700,
                  height: 40,
                  px: 2.5,
                  '&:hover': { background: 'linear-gradient(135deg, #1d4ed8 0%, #1e40af 100%)' },
                }}
                variant="contained"
              >
                Expense
              </Button>
            </Box>
          </Box>
        </Paper>

        {/* Table */}
        <Paper
          elevation={0}
          sx={{ border: '1px solid #E2E8F0', borderRadius: 2, overflow: 'hidden' }}
        >
          <Box sx={{ maxWidth: '100%', minHeight: 480, overflow: 'auto' }}>
            <ReactTable isLoading={isLoading} {...(table as Table<object>)} />
          </Box>

          {table.getTotalSize() !== 0 && (
            <PosTablePagination
              count={totalCount}
              data-testid="pos-pagination"
              onPageChange={handlePaginationChangePage}
              onRowsPerPageChange={handleChangeRowsPerPage}
              page={table.getState().pagination.pageIndex}
              rowsPerPage={table.getState().pagination.pageSize}
              rowsPerPageOptions={[5, 10, 20]}
            />
          )}
        </Paper>

        {openExpense && (
          <NewExpense
            data={expenseData}
            handleCloseDialog={() => setOpenExpense(false)}
            openModel={openExpense}
            title={`${expenseData ? t('expense:edit') : t('expense:addExpense')}`}
          />
        )}

        {openDeleteExpense && (
          <DeletePopup
            content={`${t('expense:confirmMessage')} "${expenseNameToDelete}"?`}
            handleCloseDelete={() => setOpenDeleteExpense(false)}
            onConfirm={handleDelete}
            open={openDeleteExpense}
            title={t('expense:deleteExpense')}
          />
        )}
      </Box>
    </AnimatedPage>
  );
};

export default Expense;
