import React, { useMemo, useState } from 'react';
import Button from '@mui/material/Button';
import Dialog from '@mui/material/Dialog';
import DialogActions from '@mui/material/DialogActions';
import DialogContent from '@mui/material/DialogContent';
import DialogTitle from '@mui/material/DialogTitle';
import {
  Box,
  CircularProgress,
  FormControl,
  Grid,
  TextField,
  useMediaQuery,
  Select,
  MenuItem,
  Checkbox,
  FormControlLabel,
  Typography,
} from '@mui/material';
import FieldHeader from '../../../components/FieldHeader';
import { useFormik } from 'formik';
import { theme } from '../../../theme';
import {
  useNewExpensesMutation,
  useGetAllExpenseTypeQuery,
} from '../../posApi';
import { useNotifier } from '../../../core/Notifier';
import { appColors } from '../../../theme/appColors';
import usePageQuery from '../../../core/hooks/usePageQuery';
import { useTranslation } from 'react-i18next';
import {
  IExpense,
  IExpenseTypeData,
} from '../../../core/Interface/expense.interface';
import { AdapterDayjs } from '@mui/x-date-pickers/AdapterDayjs';
import { LocalizationProvider, DatePicker } from '@mui/x-date-pickers';
import dayjs from 'dayjs';
import CreditCardIcon from '@mui/icons-material/CreditCard';
import PaymentsIcon from '@mui/icons-material/Payments';
import ReceiptIcon from '@mui/icons-material/Receipt';

interface INewExpense {
  openModel?: boolean;
  title: string;
  handleCloseDialog: (close: boolean) => void;
  data?: IExpense;
}
const NewExpense = ({
  title,
  openModel = false,
  handleCloseDialog,
  data,
}: INewExpense) => {
  const isMobile = useMediaQuery(theme.breakpoints.down('md'));
  const [newExpense, { isLoading }] = useNewExpensesMutation();
  const { showErrorMessage, showMessage } = useNotifier();
  const { t } = useTranslation(['common', 'expense']);
  const buttonText = data ? t('common:update') : t('common:create');
  const { page } = usePageQuery();
  const { data: expenseType } =
    useGetAllExpenseTypeQuery({
      pageIndex: page,
      pageSize: 10,
      searchText: '',
    });
  const [isPaid, setIsPaid] = useState(data?.isPaid || false);

  const expenseTypeList = useMemo(() => {
    return expenseType?.data as IExpenseTypeData;
  }, [expenseType]);

  const paymentType = [
    { key: 1, name: 'Cash' },
    { key: 2, name: 'Credit Card' },
    { key: 3, name: 'Bank Transfer' },
  ];

  const handleClose = () => {
    handleCloseDialog(false);
  };

  const formik = useFormik({
    initialValues: {
      id: data?.id,
      typeId: data?.typeId,
      amount: data?.amount,
      date: data?.date,
      remark: data?.remark,
      isPaid: data?.isPaid || false,
      paymentMethod: data?.paymentMethod || '',
    },
    onSubmit: async (values) => {
      try {
        const temData = {
          id: values.id,
          typeId: values.typeId,
          amount: values.amount,
          date: values.date,
          remark: values.remark,
          isPaid: values.isPaid,
          paymentMethod: values.isPaid ? String(values.paymentMethod) : null,
        };
        if (!data) {
          delete values.id;
        }

        const addExpenseResponse = await newExpense(temData).unwrap();
        if (!addExpenseResponse.status) {
          showErrorMessage(addExpenseResponse.message);
        } else {
          showMessage(addExpenseResponse.message);
          handleClose();
        }
      } catch (error) {
        showErrorMessage((error as Error).message);
      }
    },
  });

  const formValid = useMemo(() => {
    return (
      formik.values.typeId &&
      formik.values.amount &&
      formik.values.date &&
      (formik.values.isPaid ? formik.values.paymentMethod : true)
    );
  }, [formik.values]);

 const handlePaymentMethodSelect = (methodKey: number) => {
   formik.setFieldValue('paymentMethod', methodKey); 
 };

  return (
    <div>
      <form onSubmit={formik.handleSubmit}>
        <Dialog
          aria-describedby="alert-dialog-description"
          classes={{ paper: 'inherit' }}
          fullScreen={isMobile}
          fullWidth={isMobile}
          maxWidth="lg"
          open={openModel}
        >
          <DialogTitle
            sx={{
              fontWeight: 600,
              p: 3,
              backgroundColor: appColors.blueGreyishLight[30],
              borderRadius: '5px',
            }}
          >
            {title}
          </DialogTitle>
          <DialogContent
            sx={{ width: isMobile ? 'auto' : '40vw', p: 4, marginTop: '20px' }}
          >
            <Box>
              <Grid
                container
                spacing={2}
              >
                <GridItem>
                  <FieldHeader title={t('expense:title.typeName')} />
                  <FormControl sx={{ width: '100%' }}>
                    <Select
                      {...formik.getFieldProps('typeId')}
                      onChange={(e) =>
                        formik.setFieldValue('typeId', e.target.value)
                      }
                      sx={{ height: `${theme.spacing(5)}`, width: '100%' }}
                      value={formik.values.typeId}
                    >
                      {expenseTypeList &&
                        expenseTypeList.records.map((type) => (
                          <MenuItem
                            key={type.id}
                            value={type.id}
                          >
                            {type.name}
                          </MenuItem>
                        ))}
                    </Select>
                  </FormControl>
                </GridItem>

                <GridItem sx={{ pt: 2 }}>
                  <FieldHeader title={t('expense:title.amount')} />
                  <TextField
                    autoComplete="off"
                    placeholder={t('expense:title.amount')}
                    size="small"
                    {...formik.getFieldProps('amount')}
                    InputProps={{ inputProps: { min: 0 } }}
                    sx={{ height: `${theme.spacing(5)}`, width: '100%' }}
                    type="number"
                  />
                </GridItem>

                <GridItem sx={{ pt: 2 }}>
                  <FieldHeader title={t('expense:title.date')} />
                  <LocalizationProvider dateAdapter={AdapterDayjs}>
                    <DatePicker
                      InputProps={{ sx: { height: '40px' } }}
                      inputFormat="DD-MM-YYYY"
                      renderInput={(params) => (
                        <TextField
                          sx={{ height: `${theme.spacing(5)}`, width: '100%' }}
                          {...params}
                          error={Boolean(
                            formik.touched.date && formik.errors.date
                          )}
                        />
                      )}
                      {...formik.getFieldProps('date')}
                      minDate={dayjs()}
                      onChange={(date) => {
                        formik.setFieldValue('date', date);
                      }}
                      views={['day', 'month', 'year']}
                    />
                  </LocalizationProvider>
                </GridItem>

                <GridItem sx={{ pt: 2 }}>
                  <FieldHeader title={t('expense:title.remark')} />
                  <TextField
                    autoComplete="off"
                    placeholder={t('expense:title.remark')}
                    size="small"
                    {...formik.getFieldProps('remark')}
                    sx={{ height: `${theme.spacing(5)}`, width: '100%' }}
                  />
                </GridItem>

                <GridItem>
                  <FormControlLabel
                    control={
                      <Checkbox
                        checked={isPaid}
                        onChange={(event) => {
                          setIsPaid(event.target.checked);
                          formik.setFieldValue('isPaid', event.target.checked);

                          if (event.target.checked) {
                            formik.setFieldValue(
                              'paymentMethod',
                              formik.values.paymentMethod || 1
                            ); 
                          } else {
                            formik.setFieldValue('paymentMethod', ''); 
                          }
                        }}
                      />
                    }
                    label={t('expense:title.isPaid')}
                  />
                </GridItem>

                {isPaid && (
                  <Grid
                    container
                    justifyContent="space-between"
                    sx={{ ml: 2 }}
                  >
                    {paymentType.map((method) => (
                      <Grid
                        item
                        key={method.key}
                        lg={3.7}
                        md={3.8}
                        onClick={() => handlePaymentMethodSelect(method.key)}
                        sm={3.9}
                        sx={{
                          py: 0.5,
                          border: '2px solid #E6E8F3',
                          display: 'flex',
                          alignItems: 'center',
                          justifyContent: 'center',
                          flexDirection: 'column',
                          borderRadius: 2,
                          backgroundColor:
                            formik.values.paymentMethod === method.key
                              ? appColors.reflexBlue[10]
                              : 'transparent',
                          '&:hover': {
                            backgroundColor: appColors.reflexBlue[10],
                            cursor: 'pointer',
                          },
                        }}
                        xs={3.9}
                      >
                        {method.name === 'Cash' && (
                          <PaymentsIcon style={{ width: 30, height: 30 }} />
                        )}
                        {method.name === 'Credit Card' && (
                          <CreditCardIcon style={{ width: 30, height: 30 }} />
                        )}
                        {method.name === 'Bank Transfer' && (
                          <ReceiptIcon style={{ width: 30, height: 30 }} />
                        )}
                        <Typography sx={{ fontWeight: 500, fontSize: '1rem' }}>
                          {method.name}
                        </Typography>
                      </Grid>
                    ))}
                  </Grid>
                )}
              </Grid>
            </Box>
          </DialogContent>
          <DialogActions sx={{ paddingRight: '24px', p: 4, py: 3, gap: 2 }}>
            <Button
              onClick={handleClose}
              sx={{
                width: 200,
                height: 42,
                borderRadius: '5px',
              }}
              variant="outlined"
            >
              {t('common:cancel')}
            </Button>
            <Button
              autoFocus
              disabled={!formValid || isLoading}
              onClick={() => {
                formik.handleSubmit();
              }}
              sx={{
                width: 200,
                height: 42,
                borderRadius: '5px',
              }}
              type="submit"
              variant="contained"
            >
              {isLoading && (
                <Box sx={{ pr: 2, pt: 0.5 }}>
                  <CircularProgress
                    size={16}
                    sx={{ color: 'white' }}
                  />
                </Box>
              )}
              {buttonText}
            </Button>
          </DialogActions>
        </Dialog>
      </form>
    </div>
  );
};

export default React.memo(NewExpense);

// eslint-disable-next-line react/no-multi-comp
const GridItem = ({ ...rest }) => {
  return (
    <Grid
      item
      key={1}
      lg={12}
      sm={12}
      xs={12}
      {...rest}
    />
  );
};
