import React from 'react';
import { IExpense } from '../../core/Interface/expense.interface';
import { ColumnDef } from '@tanstack/react-table';
import { Box, Tooltip, Typography } from '@mui/material';
import { alpha } from '@mui/material/styles';
import { useTranslation } from 'react-i18next';
import { formatDateTime } from '../../core/utils';
import { getPriceFormat } from '../../core/utils';
import EditIcon from '@mui/icons-material/Edit';
import DeleteIcon from '@mui/icons-material/Delete';

const ActionBtn = ({
  onClick, title, color, children,
}: {
  onClick: () => void; title: string; color: string; children: React.ReactNode;
}) => (
  <Tooltip arrow title={title}>
    <Box
      onClick={(e) => { e.stopPropagation(); onClick(); }}
      sx={{
        alignItems: 'center',
        background: alpha(color, 0.1),
        border: `1px solid ${alpha(color, 0.22)}`,
        borderRadius: '7px',
        color,
        cursor: 'pointer',
        display: 'flex',
        height: 30,
        justifyContent: 'center',
        transition: 'all 0.15s',
        width: 30,
        '&:hover': { background: color, color: '#fff', transform: 'scale(1.07)' },
      }}
    >
      {children}
    </Box>
  </Tooltip>
);

const useExpenseDetailsColumn = (
  handleEdit: (data: IExpense) => void,
  handleConfirmDelete: (data: IExpense) => void
) => {
  const { t } = useTranslation(['expense']);

  return [
    {
      accessorKey: 'sn',
      header: '#',
      size: 52,
      cell: (cell) => (
        <Typography sx={{ color: alpha('#0F1D4D', 0.45), fontSize: 13, fontWeight: 600 }}>
          {cell.row.index + 1}
        </Typography>
      ),
    },
    {
      accessorKey: 'type.name',
      header: t('expense:title.typeName'),
      size: 180,
      cell: (cell) => (
        <Typography sx={{ color: '#0F1D4D', fontSize: 13, fontWeight: 600 }}>
          {(cell.getValue() as string) || '—'}
        </Typography>
      ),
    },
    {
      accessorKey: 'amount',
      header: () => <Box sx={{ textAlign: 'right' }}>{t('expense:title.amount')}</Box>,
      size: 140,
      cell: (cell) => (
        <Box sx={{ textAlign: 'right' }}>
          <Typography
            sx={{
              color: cell.row.original.amount < 0 ? '#DC2626' : '#059669',
              fontSize: 13,
              fontWeight: 700,
            }}
          >
            {getPriceFormat(cell.row.original.amount)}
          </Typography>
        </Box>
      ),
    },
    {
      accessorKey: 'dateTime',
      header: () => <Box sx={{ textAlign: 'right' }}>{t('expense:title.date')}</Box>,
      size: 180,
      cell: (cell) => (
        <Box sx={{ textAlign: 'right' }}>
          <Typography sx={{ color: '#475569', fontSize: 13 }}>
            {formatDateTime(new Date(cell.row.original.date))}
          </Typography>
        </Box>
      ),
    },
    {
      accessorKey: 'paymentMethodText',
      header: () => <Box sx={{ textAlign: 'center' }}>{t('expense:title.paymentType')}</Box>,
      size: 130,
      cell: (cell) => (
        <Box sx={{ textAlign: 'center' }}>
          <Typography sx={{ color: '#475569', fontSize: 13 }}>
            {cell.row.original.paymentMethodText}
          </Typography>
        </Box>
      ),
    },
    {
      accessorKey: 'remark',
      header: t('expense:title.remark'),
      size: 200,
      cell: (cell) => (
        <Typography sx={{ color: '#475569', fontSize: 13 }}>
          {(cell.getValue() as string) || '—'}
        </Typography>
      ),
    },
    {
      id: 'actions',
      header: '',
      size: 80,
      cell: (cell) => (
        <Box sx={{ alignItems: 'center', display: 'flex', gap: 0.75, justifyContent: 'flex-end' }}>
          <ActionBtn color="#D97706" onClick={() => handleEdit(cell.row.original)} title="Edit Expense">
            <EditIcon sx={{ fontSize: 15 }} />
          </ActionBtn>
          <ActionBtn color="#DC2626" onClick={() => handleConfirmDelete(cell.row.original)} title="Delete Expense">
            <DeleteIcon sx={{ fontSize: 15 }} />
          </ActionBtn>
        </Box>
      ),
    },
  ] as ColumnDef<IExpense>[];
};

export default useExpenseDetailsColumn;
